import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.XxxS7AoL.js";const p=JSON.parse('{"title":"Running the Hub","description":"","frontmatter":{},"headers":[],"relativePath":"hub.md","filePath":"hub.md","lastUpdated":null}'),o={name:"hub.md"};function d(n,t,l,r,h,c){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="Running-the-Hub" tabindex="-1">Running the Hub <a class="header-anchor" href="#Running-the-Hub" aria-label="Permalink to &quot;Running the Hub {#Running-the-Hub}&quot;">​</a></h1><p>How the hub itself is started and configured: the <code>slate</code> app&#39;s flags, the machine-wide <code>slate.json</code>, where Slate keeps its state on disk, and the environment variables that override any of it.</p><p>This is the deployment side. The settings a reader or an author changes from inside a notebook are in <a href="./settings">Settings</a>.</p><h2 id="serving" tabindex="-1">Serving <a class="header-anchor" href="#serving" aria-label="Permalink to &quot;Serving&quot;">​</a></h2><p>The <a href="./installation"><code>slate</code> app</a> is the normal way to run the hub:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # start (or attach to) the hub + status TUI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notebook.jl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # also open a notebook</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --own</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # force a standalone hub even if a Kaimon extension is registered</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # run the hub on this port, for this launch only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # print hub status and open notebooks, then exit (0 = up, 1 = no hub)</span></span></code></pre></div><p>The port is taken from <code>--port</code> first, then <code>KAIMONSLATE_PORT</code>, then a <code>port</code> saved in <code>slate.json</code>, then 8765. Set <code>KAIMONSLATE_NO_OPEN=1</code> to never open a browser.</p><h3 id="slate.json" tabindex="-1"><code>slate.json</code> <a class="header-anchor" href="#slate.json" aria-label="Permalink to &quot;\`slate.json\` {#slate.json}&quot;">​</a></h3><p>Machine-wide settings live in <code>slate.json</code> in your config home. Changes apply on the next hub start.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">What it sets</th></tr></thead><tbody><tr><td style="text-align:right;"><code>port</code></td><td style="text-align:right;">the hub port, unless a flag or environment variable overrides it</td></tr><tr><td style="text-align:right;"><code>worker_threads</code></td><td style="text-align:right;">default worker threads, as <code>&quot;&lt;compute&gt;,&lt;interactive&gt;&quot;</code></td></tr><tr><td style="text-align:right;"><code>worker_extra_flags</code></td><td style="text-align:right;">default extra Julia flags for workers</td></tr><tr><td style="text-align:right;"><code>memo_cap_gb</code></td><td style="text-align:right;">the <a href="./memoization">memoization</a> store&#39;s size cap</td></tr><tr><td style="text-align:right;"><code>blob_chunk_mb</code></td><td style="text-align:right;">chunk size for binary transfers</td></tr><tr><td style="text-align:right;"><code>carry_max_s</code>, <code>xfer_confirm_s</code></td><td style="text-align:right;"><a href="./regions">region</a> transfer thresholds</td></tr><tr><td style="text-align:right;"><code>remote</code></td><td style="text-align:right;">per-host timing overrides, below</td></tr><tr><td style="text-align:right;"><code>catalog</code></td><td style="text-align:right;">point the <a href="./extension-gallery">Extensions gallery</a> at a fork or mirror</td></tr></tbody></table><p><code>secrets.json</code> sits beside it and holds the <a href="./publishing">publishing</a> credentials the ledger refers to by name.</p><h3 id="Where-Slate-keeps-its-state" tabindex="-1">Where Slate keeps its state <a class="header-anchor" href="#Where-Slate-keeps-its-state" aria-label="Permalink to &quot;Where Slate keeps its state {#Where-Slate-keeps-its-state}&quot;">​</a></h3><p>Slate uses three homes, each resolved as <code>KAIMONSLATE_&lt;TYPE&gt;_HOME</code>, then <code>KAIMONSLATE_HOME/&lt;type&gt;</code>, then the XDG location:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Home</th><th style="text-align:right;">Holds</th><th style="text-align:right;">Default</th></tr></thead><tbody><tr><td style="text-align:right;">config</td><td style="text-align:right;"><code>slate.json</code>, <code>secrets.json</code></td><td style="text-align:right;"><code>~/.config/kaimonslate</code></td></tr><tr><td style="text-align:right;">data</td><td style="text-align:right;">the publishing ledger&#39;s working checkout</td><td style="text-align:right;"><code>~/.local/share/kaimonslate</code></td></tr><tr><td style="text-align:right;">cache</td><td style="text-align:right;">local site builds</td><td style="text-align:right;"><code>~/.cache/kaimonslate</code></td></tr></tbody></table><p>The cache home is safe to delete. The data home is not.</p><p>Setting <strong><code>KAIMONSLATE_HOME</code></strong> relocates all three at once, which is how you run a second hub without it sharing the first one&#39;s config, secrets and publish ledger.</p><p>To drive the hub from your own script instead, the programmatic API is still available:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KaimonSlate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">serve_notebook</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(path; host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;127.0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, port </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8765</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># blocking</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KaimonSlate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(path; port </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8765</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># non-blocking → Hub</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KaimonSlate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">stop_hub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(h)</span></span></code></pre></div><p><code>KaimonSlate.start_hub</code> / <code>open_notebook!</code> / <code>close_notebook!</code> / <code>stop_hub</code> give finer control over a multi-notebook hub. Only <code>serve_notebook</code>, <code>LiveNotebook</code>, <code>expand</code>, <code>standalone!</code>, <code>register_extension</code>, <code>export_app</code> and <code>app_defaults</code> are exported; the rest need the <code>KaimonSlate.</code> prefix. See the <a href="./api">API Reference</a>.</p><h2 id="Kernel-selection" tabindex="-1">Kernel selection <a class="header-anchor" href="#Kernel-selection" aria-label="Permalink to &quot;Kernel selection {#Kernel-selection}&quot;">​</a></h2><p>A notebook uses a <strong>gate worker</strong> whenever Kaimon&#39;s gate is available; otherwise it runs <strong>in-process</strong>. The gate worker gives you a clean namespace, a tailable log (🪵), <a href="./packages">package management</a>, and isolation. There&#39;s no setting for this. A notebook outside any Julia project still gets a worker, with an environment of its own. Restart a worker any time with <strong>⟲ Restart worker</strong> (top bar), or rebuild the namespace with <strong>↻ Rebuild</strong>.</p><p>A worker can also run on <strong>another machine</strong> — a workstation, GPU box, or cloud VM — with the notebook behaving exactly as if local. Set hosts up on the front page&#39;s <strong>🖧 Remotes</strong> dialog and place a whole notebook with <strong>Run on</strong>, or route individual cells to a named <a href="./regions">region</a> (kept warm for instant startup). See <a href="./remotes">Remotes</a>.</p><h2 id="Remote-worker-timing" tabindex="-1">Remote worker timing <a class="header-anchor" href="#Remote-worker-timing" aria-label="Permalink to &quot;Remote worker timing {#Remote-worker-timing}&quot;">​</a></h2><p>The SSH/connect/tunnel/transfer timeouts used when a worker runs on <a href="./remotes">another machine</a> default to values tuned for a LAN. A slow-auth, high-latency, or cold (heavy-precompile) host can legitimately exceed them — a cold cloud VM&#39;s first spawn, say, outrunning the 120 s dial deadline. Rather than rebuild, override any of them per machine in a <code>&quot;remote&quot;</code> object in <code>slate.json</code> (in your config home — <code>$XDG_CONFIG_HOME/kaimonslate/</code>, changes apply on the next hub start):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;remote&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dial_deadline_cold&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ssh_connect_timeout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;pkg_op_timeout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1800</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Each key also has a <code>KAIMONSLATE_*</code> environment-variable equivalent (handy for a one-off run or a test); precedence is <strong><code>slate.json</code> → env var → built-in default</strong>. Values are <strong>seconds</strong> unless noted.</p><table tabindex="0"><thead><tr><th style="text-align:right;"><code>slate.json</code> key</th><th style="text-align:right;">Env var</th><th style="text-align:right;">Default</th><th style="text-align:right;">Governs</th></tr></thead><tbody><tr><td style="text-align:right;"><code>dial_deadline_cold</code></td><td style="text-align:right;"><code>KAIMONSLATE_DIAL_DEADLINE_COLD</code></td><td style="text-align:right;"><code>120</code></td><td style="text-align:right;">Cold-spawn dial — covers remote Julia boot + KaimonGate load.</td></tr><tr><td style="text-align:right;"><code>dial_deadline_probe</code></td><td style="text-align:right;"><code>KAIMONSLATE_DIAL_DEADLINE_PROBE</code></td><td style="text-align:right;"><code>15</code></td><td style="text-align:right;">Reattach-probe / warm-pool-adopt dial.</td></tr><tr><td style="text-align:right;"><code>dial_deadline_record</code></td><td style="text-align:right;"><code>KAIMONSLATE_DIAL_DEADLINE_RECORD</code></td><td style="text-align:right;"><code>5</code></td><td style="text-align:right;">Record-first dial (a live worker answers in well under a second).</td></tr><tr><td style="text-align:right;"><code>connect_deadline_local</code></td><td style="text-align:right;"><code>KAIMONSLATE_CONNECT_DEADLINE_LOCAL</code></td><td style="text-align:right;"><code>90</code></td><td style="text-align:right;">Local (<code>127.0.0.1</code>) worker connect deadline.</td></tr><tr><td style="text-align:right;"><code>ssh_connect_timeout</code></td><td style="text-align:right;"><code>KAIMONSLATE_SSH_CONNECT_TIMEOUT</code></td><td style="text-align:right;"><code>15</code></td><td style="text-align:right;"><code>ConnectTimeout</code> for every ssh/scp/rsync op.</td></tr><tr><td style="text-align:right;"><code>ssh_control_persist</code></td><td style="text-align:right;"><code>KAIMONSLATE_SSH_CONTROL_PERSIST</code></td><td style="text-align:right;"><code>600</code></td><td style="text-align:right;">SSH connection-mux master warm-hold past the last op.</td></tr><tr><td style="text-align:right;"><code>tunnel_alive_interval</code></td><td style="text-align:right;"><code>KAIMONSLATE_TUNNEL_ALIVE_INTERVAL</code></td><td style="text-align:right;"><code>5</code></td><td style="text-align:right;">Supervised tunnel <code>ServerAliveInterval</code>.</td></tr><tr><td style="text-align:right;"><code>tunnel_alive_count</code></td><td style="text-align:right;"><code>KAIMONSLATE_TUNNEL_ALIVE_COUNT</code></td><td style="text-align:right;"><code>3</code></td><td style="text-align:right;">Supervised tunnel <code>ServerAliveCountMax</code>.</td></tr><tr><td style="text-align:right;"><code>tunnel_respawn_backoff</code></td><td style="text-align:right;"><code>KAIMONSLATE_TUNNEL_RESPAWN_BACKOFF</code></td><td style="text-align:right;"><code>1</code></td><td style="text-align:right;">Backoff after a dropped forward before respawning it.</td></tr><tr><td style="text-align:right;"><code>fwd_ready_wait</code></td><td style="text-align:right;"><code>KAIMONSLATE_FWD_READY_WAIT</code></td><td style="text-align:right;"><code>8</code></td><td style="text-align:right;">Bounded wait for an async <code>ssh -L</code> local port to start accepting before the first connect.</td></tr><tr><td style="text-align:right;"><code>probe_timeout</code></td><td style="text-align:right;"><code>KAIMONSLATE_PROBE_TIMEOUT</code></td><td style="text-align:right;"><code>4</code></td><td style="text-align:right;"><code>:direct</code> TCP port-open probe.</td></tr><tr><td style="text-align:right;"><code>firewall_giveup</code></td><td style="text-align:right;"><code>KAIMONSLATE_FIREWALL_GIVEUP</code></td><td style="text-align:right;"><code>10</code></td><td style="text-align:right;">Sustained SYN-drop ⇒ declare a firewall and fail fast.</td></tr><tr><td style="text-align:right;"><code>pkg_op_timeout</code></td><td style="text-align:right;"><code>KAIMONSLATE_PKG_OP_TIMEOUT</code></td><td style="text-align:right;"><code>900</code></td><td style="text-align:right;">Package add/rm/reconstruct — a heavy stack&#39;s resolve + precompile.</td></tr><tr><td style="text-align:right;"><code>sync_parent_timeout</code></td><td style="text-align:right;"><code>KAIMONSLATE_SYNC_PARENT_TIMEOUT</code></td><td style="text-align:right;"><code>600</code></td><td style="text-align:right;">Parent-project <code>/src</code> sync.</td></tr><tr><td style="text-align:right;"><code>blob_xfer_timeout</code></td><td style="text-align:right;"><code>KAIMONSLATE_BLOB_XFER_TIMEOUT</code></td><td style="text-align:right;"><code>600</code></td><td style="text-align:right;">Whole-binding / direct-blob boundary move.</td></tr><tr><td style="text-align:right;"><code>blob_chunk_timeout</code></td><td style="text-align:right;"><code>KAIMONSLATE_BLOB_CHUNK_TIMEOUT</code></td><td style="text-align:right;"><code>20</code></td><td style="text-align:right;">Per-chunk ZMQ recv/send timeout on a transfer.</td></tr><tr><td style="text-align:right;"><code>sysimage_lock_stale</code></td><td style="text-align:right;"><code>KAIMONSLATE_SYSIMAGE_LOCK_STALE</code></td><td style="text-align:right;"><code>1800</code></td><td style="text-align:right;">Concurrent sysimage-build lock staleness window.</td></tr><tr><td style="text-align:right;"><code>peer_bw_mbps</code></td><td style="text-align:right;"><code>KAIMONSLATE_PEER_BW_MBPS</code></td><td style="text-align:right;"><code>30</code></td><td style="text-align:right;">Assumed rate (MB/s) for an unmeasured worker→worker link.</td></tr></tbody></table><h2 id="Ollama-local-models" tabindex="-1">Ollama (local models) <a class="header-anchor" href="#Ollama-local-models" aria-label="Permalink to &quot;Ollama (local models) {#Ollama-local-models}&quot;">​</a></h2><p>The agent model dropdown lists models from your local Ollama install, queried from its HTTP API (embedding-only models are filtered out). Point at a non-default host with the standard environment variable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OLLAMA_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:11434</span></span></code></pre></div><p>Driving a local model requires Kaimon&#39;s Ollama agent backend. Selecting a model stores it as <code>ollama:&lt;name&gt;</code>, which rides each chat turn.</p><h2 id="Environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#Environment-variables" aria-label="Permalink to &quot;Environment variables {#Environment-variables}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Variable</th><th style="text-align:right;">Used for</th></tr></thead><tbody><tr><td style="text-align:right;"><code>KAIMONSLATE_PORT</code></td><td style="text-align:right;">Hub port for the <code>slate</code> app / server (default <code>8765</code>; <code>--port</code> beats it).</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_NO_OPEN</code></td><td style="text-align:right;"><code>=1</code> → never open a browser when the <code>slate</code> app starts.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_HOME</code></td><td style="text-align:right;">Sets the config, data and cache homes at once from one directory. The way to run an isolated hub.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_CONFIG_HOME</code></td><td style="text-align:right;">The config home on its own. Beats <code>KAIMONSLATE_HOME</code>.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_DATA_HOME</code></td><td style="text-align:right;">The data home on its own. Beats <code>KAIMONSLATE_HOME</code>.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_CACHE_HOME</code></td><td style="text-align:right;">The cache home on its own. Beats <code>KAIMONSLATE_HOME</code>.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_SITES_DIR</code></td><td style="text-align:right;">Local site builds, overriding the cache home&#39;s <code>sites/</code>.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_DATADIR</code></td><td style="text-align:right;">A notebook&#39;s data directory, as <code>datadir()</code> resolves it.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_NO_AUTOREGISTER</code></td><td style="text-align:right;"><code>=1</code> → do not register as a Kaimon extension on load.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_MEMO_CAP_GB</code></td><td style="text-align:right;">Size cap for the <a href="./memoization">memoization</a> store.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_MEMO_DEBUG</code></td><td style="text-align:right;"><code>=1</code> → log cache-key components.</td></tr><tr><td style="text-align:right;"><code>OLLAMA_HOST</code></td><td style="text-align:right;">Ollama API endpoint for the model list (default <code>http://127.0.0.1:11434</code>).</td></tr><tr><td style="text-align:right;"><code>VMLX_HOST</code></td><td style="text-align:right;">vmlx (MLX) API endpoint for the model list (default <code>http://127.0.0.1:8000</code>).</td></tr><tr><td style="text-align:right;"><code>SLATE_BROWSER</code></td><td style="text-align:right;">Open a specific browser (e.g. <code>&quot;Google Chrome&quot;</code>) instead of the OS default.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_ALLOWED_HOSTS</code></td><td style="text-align:right;">Extra Host/Origin names the hub will answer to (a DNS alias, a proxy). This machine&#39;s own names are admitted automatically.</td></tr><tr><td style="text-align:right;"><code>KAIMONSLATE_ASSET_BASE</code></td><td style="text-align:right;"><strong>Docs build only</strong> — points the site at the docs-assets GitHub Release for generated demo media. Unset locally → served from <code>public/assets/</code>.</td></tr></tbody></table><p>The remote-worker timing knobs above each have a <code>KAIMONSLATE_*</code> equivalent too, and a number of further variables exist for tuning transfers, regions and sysimages. Those are listed beside the code that reads them rather than here.</p>`,34)])])}const k=e(o,[["render",d]]);export{p as __pageData,k as default};
